bad.code:
if (incoming.updatedAt > stored.updatedAt) store(incoming)
// two devices edit the cart concurrently: one edit vanishes
// a fast clock on one node wins every time

better.code:
const order = compare(incoming.vv, stored.vv) // version vectors
if (order === 'after') store(incoming)
else if (order === 'concurrent') store(mergeCarts(stored, incoming))
// 'before': ignore, we already have newer data
